#################################################################
#    Disjointness Axioms
#################################################################

[]  a owl:AllDisjointClasses ;
    owl:members (
        fis:Forward
        fis:Future
        fis:Option
        fis:Swap
    ) .

[]  a owl:AllDisjointClasses ;
    owl:members (
        fis:CallOption
        fis:PutOption
    ) .

[]  a owl:AllDisjointClasses ;
    owl:members (
        fis:AmericanOption
        fis:EuropeanOption
        fis:BermudanOption
    ) .

[]  a owl:AllDisjointClasses ;
    owl:members (
        fis:Corporation
        fis:SovereignGovernment
        fis:SubSovereignGovernment
        fis:SupranationalOrganization
    ) .

[]  a owl:AllDisjointClasses ;
    owl:members (
        fis:CommonStock
        fis:PreferredStock
    ) .

[]  a owl:AllDisjointClasses ;
    owl:members (
        fis:BearerSecurity
        fis:RegisteredSecurity
        fis:BookEntrySecurity
    ) .

[]  a owl:AllDisjointClasses ;
    owl:members (
        fis:Exchange
        fis:OverTheCounterMarket
    ) .

fis:SeniorBond owl:disjointWith fis:SubordinatedBond .
fis:ExchangeTradedDerivative owl:disjointWith fis:OverTheCounterDerivative .
fis:CumulativePreferredStock owl:disjointWith fis:NonCumulativePreferredStock .
fis:MutualFund owl:disjointWith fis:ExchangeTradedFund .
fis:RetailInvestor owl:disjointWith fis:InstitutionalInvestor .
